import axios, { AxiosError, type AxiosResponse } from 'axios'
import { useSnackbar } from 'notistack'
import { useAuthHeader, useIsAuthenticated, useSignIn, useSignOut } from 'react-auth-kit'
import { useMutation, useQuery, useQueryClient } from 'react-query'
import { useNavigate } from 'react-router'

import {
  AUTH_CHANGE_PASSWORD,
  AUTH_LOGIN_MESSAGE,
  AUTH_LOGOUT_MESSAGE,
  AUTH_REGISTER_MESSAGE,
  COMMON_MESSAGE
} from 'src/data/messages'

import type { ClubLike } from 'src/models/club'
import type { User } from 'src/models/user'

export interface PutPasswordResetBody {
  newPassword: string
}
const putPasswordResetAPICall = (token: string, values: PutPasswordResetBody) => async () => {
  await axios.put(`${process.env.REACT_APP_APIHOST}/auth/password/reset?token=${token}`, values, {
    headers: { Authorization: token }
  })
}
export const useResetPassword = (token: string, values: PutPasswordResetBody) => {
  const { enqueueSnackbar } = useSnackbar()
  const navigate = useNavigate()

  return useMutation(putPasswordResetAPICall(token, values), {
    onSuccess: () => {
      enqueueSnackbar(AUTH_CHANGE_PASSWORD.CHANGE_SUCCESS_AT_EMAIL, { variant: 'success' })
      navigate('/auth/login')
    },
    onError: err => {
      if (err instanceof AxiosError) {
        enqueueSnackbar(err.response?.data?.message ?? AUTH_CHANGE_PASSWORD.SERVER_ERROR, { variant: 'error' })
        return
      }

      enqueueSnackbar(AUTH_CHANGE_PASSWORD.UNKNOWN_ERROR, { variant: 'error' })
    }
  })
}

