export interface LoginAPIBody {
  email: string | null
  password: string | null
}

export interface LoginAPIResponse extends AxiosResponse {
  accessToken: string
  expiresIn: string
  refreshToken: string
  refreshTokenExpiresIn: string
  user: {
    id: number
    name: string
    studentId: string
    phoneNumber: string
    email: string
    department: string
    nickname: string
  }
  clubs: {
    id: number
    name: string
    isAdmin: boolean
  }
  likes: ClubLike
}

const postLoginAPICall = (values: LoginAPIBody) => async () => {
  return await axios.post<LoginAPIResponse>(`${process.env.REACT_APP_APIHOST}/auth/login`, values)
}
export const useLogin = (values: LoginAPIBody) => {
  const { enqueueSnackbar } = useSnackbar()
  const navigate = useNavigate()
  const signIn = useSignIn()
  const client = useQueryClient()

  return useMutation(postLoginAPICall(values), {
    onSuccess: ({ data }) => {
      if (
        signIn({
          token: data.accessToken,
          expiresIn: Math.ceil(parseInt(data.expiresIn) / 60),
          tokenType: 'Bearer',
          authState: { clubs: data.clubs, likes: data.likes, ...data.user },
          refreshToken: data.refreshToken,
          refreshTokenExpireIn: Math.ceil(parseInt(data.refreshTokenExpiresIn) / 60)
        })
      ) {
        client.setQueryData('user', { clubs: data.clubs, likes: data.likes, ...data.user })
        enqueueSnackbar(`${AUTH_LOGIN_MESSAGE.SUCCESS}, ${data.user.nickname} 님!`, { variant: 'success' })
        navigate('/')
      } else enqueueSnackbar(AUTH_LOGIN_MESSAGE.SUCCESS, { variant: 'error' })
    },
    onError: err => {
      if (err instanceof AxiosError) {
        enqueueSnackbar(err.response?.data?.message ?? COMMON_MESSAGE.SERVER_ERROR, { variant: 'error' })
        return
      }

      enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
    }
  })
}

type PostLogoutRequestBody = null
const postLogoutAPICall = (token: string) => async () => {
  await axios.post<null, AxiosResponse<null>, PostLogoutRequestBody>(
    `${process.env.REACT_APP_APIHOST}/auth/logout`,
    null,
    {
      headers: { Authorization: token }
    }
  )
}
export const useLogout = (successMessage: string) => {
  const { enqueueSnackbar } = useSnackbar()
  const navigate = useNavigate()
  const signOut = useSignOut()
  const token = useAuthHeader()()
  const isAuthenticated = useIsAuthenticated()

  if (!isAuthenticated()) {
    return {
      mutate: () => {
        enqueueSnackbar(AUTH_LOGOUT_MESSAGE.WRONG, { variant: 'error' })
      },
      mutateAsync: () => {
        enqueueSnackbar(AUTH_LOGOUT_MESSAGE.WRONG, { variant: 'error' })
      }
    }
  }

  return useMutation(postLogoutAPICall(token), {
    onSuccess: () => {
      if (signOut()) {
        enqueueSnackbar(successMessage, { variant: 'success' })
        navigate('/', { replace: true })
      } else {
        enqueueSnackbar(AUTH_LOGOUT_MESSAGE.FAIL, { variant: 'error' })
      }
    },
    onError: err => {
      if (err instanceof AxiosError) {
        enqueueSnackbar(err.response?.data?.message ?? AUTH_LOGOUT_MESSAGE.SERVER_ERROR, { variant: 'error' })
        return
      }

      enqueueSnackbar(AUTH_LOGOUT_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
    }
  })
}

