// @ts-nocheck
import { rest } from 'msw'

import type { PostAuthPasswordRequestBody } from 'src/api/auth'

import type { Permission } from 'src/models/permission'

interface UserRequestBody {}
interface UserRequestParams {}
interface UserResponseBody {
  user: {
    id: number
    name: string
    studentId: string
    phoneNumber: string
    email: string
    department: string
    nickname: string
  }
  clubs: Array<{
    id: number
    name: string
    permission: Permission
    isConnected: boolean
  }>
}

interface UpdateUserRequestBody {
  nickname: string
  name: string
  department: string
  phoneNumber: string
}
interface UpdateUserRequestParams {}
interface UpdateUserResponseBody {
  nickname: string
  name: string
  department: string
  phoneNumber: string
}

interface UpdatePasswordRequestBody {
  currentPassword: string
  newPassword: string
}
interface UpdatePasswordRequestParams {}
interface UpdatePasswordResponseBody {}

export const UserHandlers = [
  // User API
  rest.get<UserRequestBody, UserRequestParams, UserResponseBody>('/user', (req, res, ctx) => {
    const accessToken = req.headers.get('Authorization')
    if (accessToken !== 'Bearer ACCESS_TOKEN') {
      return res(ctx.status(401, 'invalid user!'), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'))
    }

    const responseData: UserResponseBody = {
      user: {
        id: 1,
        email: 'gildonghong@korea.ac.kr',
        studentId: '2020320000',
        name: '김dd',
        nickname: '축지법 달인',
        department: '정보대학 컴퓨터학과',
        phoneNumber: '010-1234-1234'
      },
      clubs: [
        {
          id: 1,
          name: 'KWEB',
          permission: 'SUPERADMIN',
          isConnected: true,
          semester: 'SPRING',
          year: 2023,
          searchable: true
        },
        {
          id: 2,
          name: 'KUICS',
          permission: 'ADMIN',
          isConnected: false,
          semester: 'FALL',
          year: 2022,
          searchable: false
        },
        {
          id: 3,
          name: '그루터기',
          permission: 'USER',
          isConnected: false,
          semester: 'SPRING',
          year: 2023,
          searchable: true
        },
        {
          id: 4,
          name: 'AIKU',
          permission: 'USER',
          isConnected: true,
          semester: 'SPRING',
          year: 2023,
          searchable: true
        }
      ]
    }

    return res(ctx.status(200), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'), ctx.json(responseData))
  }),
  rest.put<UpdateUserRequestBody, UpdateUserRequestParams, UpdateUserResponseBody>('/user', async (req, res, ctx) => {
    const accessToken = req.headers.get('Authorization')
    if (accessToken !== 'Bearer ACCESS_TOKEN') {
      return res(ctx.status(401, 'invalid user!'), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'))
    }
    const { nickname, name, department, phoneNumber } = await req.json()
    if (nickname === null || department === null || phoneNumber === null) {
      return res(ctx.status(400), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'))
    }
    return res(
      ctx.status(200),
      ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'),
      ctx.json({ nickname, name, department, phoneNumber })
    )
  }),
  rest.post<PostAuthPasswordRequestBody, Record<string, never>, Record<string, never>>(
    '/auth/password',
    async (req, res, ctx) => {
      const { email } = await req.json()
      if (email === null) {
        return res(ctx.status(400), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'))
      }
      return res(ctx.status(200), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'))
    }
  ),
  rest.put<UpdatePasswordRequestBody, UpdatePasswordRequestParams, UpdatePasswordResponseBody>(
    '/auth/password',
    async (req, res, ctx) => {
      const accessToken = req.headers.get('Authorization')
      if (accessToken !== 'Bearer ACCESS_TOKEN') {
        return res(ctx.status(401, 'invalid user!'), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'))
      }
      const { currentPassword, newPassword } = await req.json()
      if (currentPassword === null || newPassword === null) {
        return res(ctx.status(400), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'))
      }
      if (currentPassword === 'notmatch') {
        return res(
          ctx.status(401, 'password does not match!'),
          ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000')
        )
      }
      return res(ctx.status(200), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'))
    }
  ),
  rest.delete('/user', async (req, res, ctx) => {
    return res(
      ctx.status(200),
      ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'),
      ctx.json({ message: 'ok' })
    )
  })
]
