import { useAuthUser } from 'react-auth-kit'

import type { User } from 'src/models/user'
import { isUserType } from 'src/utils/typeChecker'

type UseSafeAuthUserReturn =
  | { isLoggedIn: false; userInfo: null }
  | { isLoggedIn: true; userInfo: null }
  | { isLoggedIn: true; userInfo: User }

const useSafeAuthUser = (): UseSafeAuthUserReturn => {
  const authState = useAuthUser()
  const userInfo = authState()

  if (!userInfo) return { isLoggedIn: false, userInfo: null }
  if (!isUserType(userInfo)) return { isLoggedIn: true, userInfo: null }
  return { isLoggedIn: true, userInfo }
}

export default useSafeAuthUser
