import React from 'react'
import { useIsAuthenticated } from 'react-auth-kit'

import MenuIcon from '@mui/icons-material/Menu'
import { Box, Button, IconButton, alpha, lighten, useMediaQuery, useTheme } from '@mui/material'
import { styled } from '@mui/material/styles'

import Userbox from 'src/components/Header/Userbox'
import Logo from 'src/components/Logo'

import type { SidebarProps } from 'src/layouts/SidebarLayout'

const HeaderWrapper = styled(Box)(
  ({ theme }) => `
      background-color: ${alpha(String(theme.header.background), 0.95)};
      color: ${theme.header.textColor};
      position: sticky;
      top: 0;
      right: 0;
      z-index: 6;
      display: flex;
      flex-direction: row;
      justify-content: space-between;
      align-items: center;
      width: 100%;
      backdrop-filter: blur(3px);
  `
)

const HeaderItemWrapper = styled(Box)(
  () => `
      flex: 1;
      display: flex;
      flex-direction: row;
      align-items: center;
  `
)

const Header: React.FC<SidebarProps> = ({ handleDrawerClick }) => {
  const theme = useTheme()
  const isPc = useMediaQuery(theme.breakpoints.up('lg'))
  const isAuthenticated = useIsAuthenticated()
  const isNotRegisterPage = window.location.pathname != '/club/register'
  return (
    <HeaderWrapper
      sx={{
        boxShadow:
          theme.palette.mode === 'dark'
            ? `0 1px 0 ${alpha(
                lighten(theme.colors.primary.main, 0.7),
                0.15
              )}, 0px 2px 8px -3px rgba(0, 0, 0, 0.2), 0px 5px 22px 4px rgba(0, 0, 0, .1)`
            : `0px 2px 8px -3px ${alpha(theme.colors.alpha.black[100], 0.2)}, 0px 5px 22px -4px ${alpha(
                theme.colors.alpha.black[100],
                0.1
              )}`,
        padding: isPc ? theme.spacing(0, 3) : theme.spacing(0, 2),
        justifyContent: 'space-between',
        height: isPc ? theme.header.height : 52
      }}
    >
      {!(isPc && isNotRegisterPage) && (
        <HeaderItemWrapper justifyContent={'flex-start'}>
          <IconButton onClick={handleDrawerClick}>
            <MenuIcon />
          </IconButton>
        </HeaderItemWrapper>
      )}
      <HeaderItemWrapper justifyContent={isPc && isNotRegisterPage ? 'flex-start' : 'center'}>
        <Logo />
      </HeaderItemWrapper>
      <HeaderItemWrapper justifyContent={'flex-end'}>
        {!isAuthenticated() && <Button href="/auth/login">로그인</Button>}
        {isAuthenticated() && <Userbox />}
      </HeaderItemWrapper>
    </HeaderWrapper>
  )
}

export default Header
